fn main(){println!("UNICODE {:?}",char::UNICODE_VERSION);for (name,predicate) in [("alphabetic",char::is_alphabetic as fn(char)->bool),("numeric",char::is_numeric as fn(char)->bool)]{let mut start=None;for cp in 0..=0x110000{let yes=char::from_u32(cp).map_or(false,predicate);match(start,yes){(None,true)=>start=Some(cp),(Some(low),false)=>{println!("{} {} {}",name,low,cp-1);start=None;},_=>{}}}}}
